SELECT id, trace_id, user_id, username, user_message, final_reply, status, error_message, total_cost_ms, tool_count, create_time, update_time, is_deleted FROM agent_trace WHERE is_deleted = 0
AND user_id = #{userId}
AND status = #{status}
AND ( trace_id LIKE CONCAT('%', #{keyword}, '%') OR username LIKE CONCAT('%', #{keyword}, '%') OR user_message LIKE CONCAT('%', #{keyword}, '%') OR final_reply LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY create_time DESC
